#Requires -Version 5.1
<#
.SYNOPSIS
    Pretty Configuration Manager - Diagnostic Test Suite
    Run this and paste tests\\last-report.txt back to Claude for analysis.
.USAGE
    powershell -ExecutionPolicy Bypass -File .\\tests\\Run-Tests.ps1
#>

Set-StrictMode -Off
