$repoRoot   = if \($PSScriptRoot -match 'tests\) { Split-Path $PSScriptRoot -Parent } else { $PSScriptRoot }
$moduleFile = Join-Path $repoRoot 'src\\SignatureManager.psm1'
$uiFile     = Join-Path $repoRoot 'src\\Ui.ps1'

# Report scaffolding
$results = [System.Collections.Generic.List[PSCustomObject]]::new\(\)
$pass = 0; $fail = 0; $skip = 0

function Test-Case {
    param\([string]$Group, [string]$Name, [scriptblock]$Test\)
    $status = 'PASS'
    $detail = ''
    try {
        $msg = & $Test
        $detail = if \($msg\) { $msg } else { 'OK' }
        $script:pass++
    } catch {
        $status = 'FAIL'
        $detail = $_.Exception.Message -replace '\\r?\\n', ' | '
        $script:fail++
    }
    $script:results.Add\([PSCustomObject]@{ Group = $Group; Name = $Name; Status = $status; Detail = $detail }\)
}

function Skip-Case {
    param\([string]$Group, [string]$Name, [string]$Reason\)
    $script:results.Add\([PSCustomObject]@{ Group = $Group; Name = $Name; Status = 'SKIP'; Detail = $Reason }\)
    $script:skip++
}

