New-Item -ItemType Directory -Path $sandbox | Out-Null

# Patch module to use sandbox path instead of real Signatures folder
$moduleContent = Get-Content -Path $moduleFile -Raw
$escapedSandbox = $sandbox -replace '\\\\', '\\\\\\\\'
$moduleContent = $moduleContent -replace [regex]::Escape\("Join-Path `$env:APPDATA 'Microsoft\\Signatures'"\), \('"' + $escapedSandbox + '"'\)
