# ── Group 14: Settings \(child process to avoid WPF dependency\) ────────────────
$settingsGroup = 'Settings \(Ui.ps1\)'
$tmpSettingsFile = Join-Path $sandbox '_settings.json'

$probe = @"
`$script:SettingsPath = '$\($tmpSettingsFile -replace '\\\\', '\\\\'\)'
`$script:Themes = [ordered]@{
    'Dark'    = @{ BgBrush = '#000' }
    'Light'   = @{ BgBrush = '#FFF' }
    'Crimson' = @{ BgBrush = '#1A1' }
}
function Load-Settings {
    `$defaults = [PSCustomObject]@{ Theme = 'Dark'; Language = 'en' }
    if \(-not \(Test-Path `$script:SettingsPath\)\) { return `$defaults }
    try {
        `$obj = Get-Content -Path `$script:SettingsPath -Raw -Encoding UTF8 | ConvertFrom-Json
        if \(-not `$script:Themes.Contains\(`$obj.Theme\)\) { `$obj.Theme = 'Dark' }
        return `$obj
    } catch { return `$defaults }
}
function Save-Settings {
    param\([PSCustomObject]`$Settings\)
    `$dir = Split-Path `$script:SettingsPath -Parent
    if \(-not \(Test-Path `$dir\)\) { New-Item -ItemType Directory -Path `$dir -Force | Out-Null }
    try { `$Settings | ConvertTo-Json -Depth 3 | Set-Content -Path `$script:SettingsPath -Encoding UTF8 } catch {}
}
`$d = Load-Settings
if \(`$d.Theme -ne 'Dark'\) { Write-Error 'DEFAULT_FAIL'; exit 1 }
`$s = [PSCustomObject]@{ Theme = 'Light'; Language = 'en' }
Save-Settings -Settings `$s
`$loaded = Load-Settings
if \(`$loaded.Theme -ne 'Light'\) { Write-Error 'ROUNDTRIP_FAIL'; exit 1 }
`$bad = [PSCustomObject]@{ Theme = 'Nonexistent'; Language = 'en' }
Save-Settings -Settings `$bad
`$fallback = Load-Settings
if \(`$fallback.Theme -ne 'Dark'\) { Write-Error 'FALLBACK_FAIL'; exit 1 }
Write-Output 'SETTINGS_OK'
"@

$tmpProbe = Join-Path $sandbox '_settings_probe.ps1'
Set-Content -Path $tmpProbe -Value $probe -Encoding UTF8

try {
    $out = powershell -NoProfile -ExecutionPolicy Bypass -File $tmpProbe 2>&1
    $outStr = $out -join ' '
    Test-Case $settingsGroup 'Defaults returned when file absent' {
        if \($outStr -match 'SETTINGS_OK'\) { 'OK' } else { throw \('Probe failed: ' + $outStr\) }
    }
    Test-Case $settingsGroup 'Theme persists and loads correctly' {
        if \($outStr -match 'SETTINGS_OK'\) { 'Round-trip OK' } else { throw \('Probe failed: ' + $outStr\) }
    }
    Test-Case $settingsGroup 'Unknown theme falls back to Dark' {
        if \($outStr -match 'SETTINGS_OK'\) { 'Fallback OK' } else { throw \('Probe failed: ' + $outStr\) }
    }
} catch {
    Skip-Case $settingsGroup 'Settings tests \(3\)' \('Child process error: ' + $_\)
}

