# ── Print report ──────────────────────────────────────────────────────────────
$line = '-' * 70
Write-Host ''
Write-Host 'PRETTY CONFIGURATION MANAGER - TEST REPORT' -ForegroundColor Cyan
Write-Host \(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'\) -ForegroundColor DarkGray
Write-Host ''

$groups = $results | Select-Object -ExpandProperty Group -Unique
foreach \($group in $groups\) {
    Write-Host \('  > ' + $group\) -ForegroundColor Yellow
    $results | Where-Object Group -eq $group | ForEach-Object {
        $color = if \($_.Status -eq 'PASS'\) { 'Green' } elseif \($_.Status -eq 'FAIL'\) { 'Red' } else { 'DarkYellow' }
        $icon  = if \($_.Status -eq 'PASS'\) { '[PASS]' } elseif \($_.Status -eq 'FAIL'\) { '[FAIL]' } else { '[SKIP]' }
        Write-Host \('    ' + $icon + ' ' + $_.Name\) -ForegroundColor $color
        if \($_.Status -ne 'PASS'\) {
            Write-Host \('      -> ' + $_.Detail\) -ForegroundColor DarkGray
        }
    }
    Write-Host ''
}

Write-Host $line
$total = $pass + $fail + $skip
Write-Host \('  ' + $pass + ' passed  |  ' + $fail + ' failed  |  ' + $skip + ' skipped  |  ' + $total + ' total'\) -ForegroundColor White
Write-Host $line

if \($fail -gt 0\) {
    Write-Host ''
    Write-Host 'FAILED:' -ForegroundColor Red
    $results | Where-Object Status -eq 'FAIL' | ForEach-Object {
        Write-Host \('  [' + $_.Group + '] ' + $_.Name\) -ForegroundColor Red
        Write-Host \('    ' + $_.Detail\) -ForegroundColor DarkGray
    }
}

Write-Host ''

# Save plain-text report
$reportLines = [System.Collections.Generic.List[string]]::new\(\)
$reportLines.Add\('=== PRETTY CONFIGURATION MANAGER TEST REPORT ==='\)
$reportLines.Add\('Run: ' + \(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'\)\)
$reportLines.Add\('Results: ' + $pass + ' passed / ' + $fail + ' failed / ' + $skip + ' skipped / ' + $total + ' total'\)
$reportLines.Add\(''\)
foreach \($r in $results\) {
    $reportLines.Add\('[' + $r.Status + '] ' + $r.Group + ' > ' + $r.Name\)
    if \($r.Status -ne 'PASS'\) {
        $reportLines.Add\('  detail: ' + $r.Detail\)
    }
}

$reportPath = Join-Path $repoRoot 'tests\\last-report.txt'
$reportLines | Set-Content -Path $reportPath -Encoding UTF8
Write-Host '  Report saved to: tests\\last-report.txt' -ForegroundColor DarkGray
Write-Host '  Paste it back to Claude for analysis.' -ForegroundColor DarkGray
Write-Host ''
ENDOFSCRIPT)
